# Confine the service-principal trust to this account
resource "aws_iam_role" "<example_resource_name>" {
  name = "<example_resource_name>"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "<service>.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = { "aws:SourceAccount" = data.aws_caller_identity.current.account_id }
          # Optional but preferred: bind to the calling resource as well.
          ArnLike      = { "aws:SourceArn" = aws_<service>_<resource>.example.arn }
        }
      }
    ]
  })
}
